#!/usr/bin/env node
/**
 * mms-ds — the prototyping entry point for @mms/design-system.
 *
 *   npx mms-ds start     scaffold index.html, serve it, open the browser
 *   npx mms-ds init      scaffold index.html and stop
 *
 * Why this exists at all
 * ──────────────────────
 * The prototype path used to be two manual steps: create an index.html by hand
 * from a code block in the docs, then "open it through a local web server."
 * Both are manual configuration, and manual configuration is where adoption
 * dies. Worse, neither can be reduced to a copy-pasteable command: writing a
 * file from a shell is `cat <<EOF` on bash and `Set-Content` on PowerShell, and
 * a bash-only snippet in the install guide is precisely the defect DS-163
 * exists to fix. Node runs identically on every platform we support, so the
 * command that does this has to be a Node program.
 *
 * Deliberately zero-dependency. This ships inside the published package, and a
 * package that claims zero runtime dependencies cannot pull in a static-server
 * library to honour that claim. Everything here is Node builtins.
 */

import { createServer } from 'http';
import { spawn } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const CWD = process.cwd();
const DEFAULT_PORT = 8080;
const PORT_ATTEMPTS = 20;

// Maximus is the starting brand, matching every other example we publish. It is
// deliberately not `default` — that theme is the neutral greyscale fallback used
// for token development, and a brandless grey page is a poor first impression of
// a design system whose whole point is brand portability.
const DEFAULT_THEME = 'maximus';

// Themes that ship and resolve, but are never *offered* as a choice. `default`
// is the neutral greyscale sheet token development is authored against — it is
// not a brand, and the Storybook Themes page hides it for exactly that reason.
// Advertising it here while hiding it there would make one of the two wrong.
//
// Still accepted when named explicitly: it does resolve, and rejecting a theme
// the package genuinely contains is a lie the filesystem can disprove.
const UNLISTED_THEMES = ['default'];

// ── Content types ───────────────────────────────────────────────────
//
// Not cosmetic. A browser refuses to execute a <script type="module"> that
// arrives without a JavaScript content type — it fails with a strict MIME
// check, not a 404, which reads as "the bundle is broken" rather than "the
// server mislabelled it." Serving .js correctly is the whole reason this is a
// real server and not a two-line file dump.

const CONTENT_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.ttf': 'font/ttf',
  '.otf': 'font/otf',
};

// ── Locating the bundle ─────────────────────────────────────────────

/**
 * Resolve dist/standalone.js and express it relative to the consumer's folder.
 *
 * This file lives at dist/mms-ds.mjs in the published package, so the bundle is
 * its sibling. Resolving from `import.meta.url` rather than assuming
 * `./node_modules/@mms/design-system/dist/` means the generated page is correct
 * under npm hoisting, nested installs and workspaces alike.
 *
 * The returned path is relative on purpose: the scaffolded index.html then
 * works under *any* static server, not just this one. A page that only renders
 * under `mms-ds start` would be a dead artifact the moment someone moves it
 * into a real project.
 */
function resolveStandalone() {
  const abs = path.join(HERE, 'standalone.js');

  if (!fs.existsSync(abs)) {
    fail(
      `Could not find the standalone bundle at ${abs}.`,
      'The package looks incomplete — try reinstalling:',
      '  npm install @mms/design-system'
    );
  }

  const rel = path.relative(CWD, abs);

  // Outside the current folder means the package was installed somewhere this
  // page cannot reference — a global install, or npx running straight from its
  // cache with nothing installed locally. Say so plainly instead of writing an
  // index.html with a path that silently 404s.
  if (rel.startsWith('..') || path.isAbsolute(rel)) {
    fail(
      '@mms/design-system is not installed in this folder.',
      'Install it here first, then run this again:',
      '  npm install @mms/design-system',
      '  npx mms-ds start'
    );
  }

  // Always POSIX separators — this goes into an HTML src attribute, and a
  // Windows backslash path is not a valid URL.
  return './' + rel.split(path.sep).join('/');
}

/**
 * List the brand themes this installed copy actually ships.
 *
 * Read from dist/themes/ rather than hardcoded here. A hardcoded list is a
 * second manifest that silently drifts: add a client theme and `--theme` keeps
 * rejecting it, remove one and `--theme` keeps offering a name that no longer
 * resolves. The filesystem is the only source that cannot go stale.
 *
 * Filtered on purpose:
 *  - `*-dark.css` — not selectable brands. Dark is a *mode*, applied on top of a
 *    brand via data-mode / prefers-color-scheme, so offering `maximus-dark` as a
 *    theme would misrepresent the model.
 *  - directories — themes/<name>/ holds brand font assets, not a theme sheet.
 */
function discoverThemes() {
  const dir = path.join(HERE, 'themes');

  // Empty rather than fatal. An incomplete package is already reported — loudly
  // and with the right instruction — by resolveStandalone(), which runs on every
  // scaffold. Duplicating that check here would only mean `--help` refuses to
  // print on a broken install, which helps nobody.
  if (!fs.existsSync(dir)) return [];

  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter(entry => entry.isFile() && entry.name.endsWith('.css') && !entry.name.endsWith('-dark.css'))
    .map(entry => entry.name.slice(0, -'.css'.length))
    .sort();
}

/**
 * The subset of installed themes worth showing a consumer.
 *
 * Kept separate from discoverThemes() rather than filtered inside it, because
 * the two answer different questions: "what resolves?" governs validation, and
 * "what should we suggest?" governs help text and the scaffolded comment.
 * Collapsing them would silently turn a hidden theme into a rejected one.
 */
function offeredThemes(themes) {
  return themes.filter(name => !UNLISTED_THEMES.includes(name));
}

// ── Scaffolding ─────────────────────────────────────────────────────

function template(standalonePath, theme, themes) {
  const others = offeredThemes(themes)
    .filter(name => name !== theme)
    .join(' | ') || '(none installed)';

  return `<!DOCTYPE html>
<html lang="en" data-theme="${theme}">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Maximus Design System — prototype</title>

    <!--
      One script tag, nothing else. This bundle carries Lit, every component,
      the icon set and all design tokens, and applies whichever theme is set on
      <html> above. There is no build step and no import map.

      Swap data-theme on <html> above to try another brand — every theme is
      already inside the bundle, nothing more to install:
      ${others}

      Dark mode follows your OS automatically. To pin it instead, add
      data-mode="dark" (or "light") alongside data-theme.

      Brand fonts are not bundled. Each theme names its real typeface first and
      falls back to a widely-installed substitute, so type is readable
      everywhere and exact wherever the licensed font is already installed.
    -->
    <script type="module" src="${standalonePath}"></script>

    <style>
      body {
        margin: 0;
        padding: 2rem;
        /* The active theme's body face. --font-family-heading and
           --font-family-tabular are the other two. */
        font-family: var(--font-family-body, Arial, sans-serif);
        /* The page-level surface token. Deliberately not pure white: white is
           its own opt-in token (--color-surface-solid) so a solid card has
           something to read against. */
        background: var(--color-surface-page, #fcfcfc);
        color: var(--color-text-default, #111);
      }
      main { max-width: 40rem; margin: 0 auto; display: grid; gap: 1.5rem; }
      .row { display: flex; gap: 0.75rem; flex-wrap: wrap; }
    </style>
  </head>
  <body>
    <main>
      <h1>Maximus Design System</h1>
      <p>Edit this file and refresh. Every <code>mms-*</code> element is already available.</p>

      <div class="row">
        <mms-button variant="primary" label="Primary"></mms-button>
        <mms-button variant="secondary" label="Secondary"></mms-button>
        <mms-button variant="ghost" label="Ghost"></mms-button>
      </div>

      <mms-text-field label="Full name" placeholder="Jane Doe"></mms-text-field>

      <mms-checkbox label="I have read the terms"></mms-checkbox>
    </main>
  </body>
</html>
`;
}

function scaffold(theme, themes) {
  const target = path.join(CWD, 'index.html');

  if (fs.existsSync(target)) {
    return { target, created: false };
  }

  fs.writeFileSync(target, template(resolveStandalone(), theme, themes), 'utf8');
  return { target, created: true };
}

// ── Static server ───────────────────────────────────────────────────

function serve(port) {
  const server = createServer((req, res) => {
    // Strip the query string before touching the filesystem, and decode percent
    // escapes so a path with a space resolves.
    let pathname;
    try {
      pathname = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
    } catch {
      res.writeHead(400).end('Bad request');
      return;
    }

    let file = path.resolve(CWD, '.' + pathname);

    // Containment backstop. The WHATWG URL parser already collapses `..`
    // segments out of `pathname` (verified: /../../etc/passwd and its
    // percent-encoded form both resolve inside the served folder and 404), so
    // on POSIX this rarely fires. It is kept because that is not the only way
    // to escape: on Windows path.resolve treats a backslash as a separator and
    // the URL parser does not, so a `..\..\` path reaches here intact. Comparing
    // the *resolved* path against the root catches both, where inspecting the
    // raw URL for ".." would catch neither reliably.
    if (file !== CWD && !file.startsWith(CWD + path.sep)) {
      res.writeHead(403).end('Forbidden');
      return;
    }

    if (fs.existsSync(file) && fs.statSync(file).isDirectory()) {
      file = path.join(file, 'index.html');
    }

    if (!fs.existsSync(file) || !fs.statSync(file).isFile()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end(`404 — ${pathname}`);
      return;
    }

    res.writeHead(200, {
      'Content-Type': CONTENT_TYPES[path.extname(file).toLowerCase()] || 'application/octet-stream',
      // The point of this server is editing a file and hitting refresh. A
      // cached bundle or a cached page makes that look broken.
      'Cache-Control': 'no-store',
    });
    fs.createReadStream(file).pipe(res);
  });

  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(port, () => resolve(server));
  });
}

/**
 * Take the first free port at or above `start`.
 *
 * 8080 is very often already taken on a working developer machine. Failing with
 * EADDRINUSE and making the consumer pick a number is exactly the kind of
 * incidental decision this command exists to remove.
 */
async function listen(start) {
  for (let port = start; port < start + PORT_ATTEMPTS; port++) {
    try {
      return { server: await serve(port), port };
    } catch (error) {
      if (error.code !== 'EADDRINUSE') throw error;
    }
  }
  fail(
    `Ports ${start}–${start + PORT_ATTEMPTS - 1} are all in use.`,
    'Pick one explicitly:',
    '  npx mms-ds start --port 4000'
  );
}

// ── Browser ─────────────────────────────────────────────────────────

/**
 * Open the default browser, best-effort.
 *
 * Never fatal: headless CI, a locked-down VM, or no desktop session are all
 * normal. The URL is always printed, so a failure here costs one click.
 */
function openBrowser(url) {
  const [cmd, args] =
    process.platform === 'darwin'
      ? ['open', [url]]
      : process.platform === 'win32'
        ? // The empty string is the window title. Without it, `start` treats a
          // quoted URL as the title and opens nothing.
          ['cmd', ['/c', 'start', '', url]]
        : ['xdg-open', [url]];

  try {
    const child = spawn(cmd, args, { stdio: 'ignore', detached: true });
    child.on('error', () => {});
    child.unref();
  } catch {
    /* printed above — not worth interrupting for */
  }
}

// ── CLI ─────────────────────────────────────────────────────────────

function fail(...lines) {
  console.error('\n✗ ' + lines.join('\n  ') + '\n');
  process.exit(1);
}

function help(themes) {
  // "brands", not "installed" — this is the offered subset, and `default` ships
  // without appearing here. Labelling a filtered list "installed" would be the
  // same inaccuracy in the opposite direction.
  const list = offeredThemes(themes).join(', ') || '—';

  return `
  mms-ds — prototype with the Maximus Design System

  Usage
    npx mms-ds start          create index.html, serve it, open the browser
    npx mms-ds init           create index.html and stop

  Options
    --theme <name>            brand to start on (default ${DEFAULT_THEME})
                              brands: ${list}
    --port <number>           port to serve on (default ${DEFAULT_PORT})
    --no-open                 do not launch a browser
    -h, --help                show this

  Every theme ships inside the bundle. --theme only picks which one the new
  index.html starts on — switch any time by editing data-theme on <html>.
`;
}

function parseArgs(argv, themes) {
  const options = { port: DEFAULT_PORT, open: true, theme: DEFAULT_THEME, themeGiven: false };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--no-open') {
      options.open = false;
    } else if (arg === '--port') {
      const value = Number(argv[++i]);
      if (!Number.isInteger(value) || value < 1 || value > 65535) {
        fail(`--port expects a number between 1 and 65535, got "${argv[i]}".`);
      }
      options.port = value;
    } else if (arg === '--theme') {
      const value = argv[++i];
      if (!value || value.startsWith('--')) {
        fail('--theme expects a theme name.', `Brands: ${offeredThemes(themes).join(', ')}`);
      }
      // themes is empty only when the package is incomplete — resolveStandalone()
      // reports that properly a moment later, so don't reject a valid name here
      // with a misleading "unknown theme" message.
      //
      // Validated against every theme that resolves, not just the offered ones:
      // `--theme default` is unadvertised, not unsupported.
      if (themes.length && !themes.includes(value)) {
        fail(
          `Unknown theme "${value}".`,
          `Brands: ${offeredThemes(themes).join(', ')}`
        );
      }
      options.theme = value;
      options.themeGiven = true;
    } else {
      fail(`Unknown option "${arg}".`, 'Run `npx mms-ds --help` for usage.');
    }
  }

  return options;
}

async function main() {
  const [command, ...rest] = process.argv.slice(2);
  const themes = discoverThemes();

  if (!command || command === '-h' || command === '--help' || command === 'help') {
    console.log(help(themes));
    return;
  }

  if (command !== 'start' && command !== 'init') {
    fail(`Unknown command "${command}".`, 'Run `npx mms-ds --help` for usage.');
  }

  const options = parseArgs(rest, themes);
  const { target, created } = scaffold(options.theme, themes);
  const name = path.relative(CWD, target) || 'index.html';

  if (created) {
    console.log(`\n✓ Created ${name} — theme: ${options.theme}`);
  } else {
    console.log(`\n• Using the ${name} already in this folder`);
    // Saying nothing here would look like --theme was applied and ignored.
    if (options.themeGiven) {
      console.log(`  --theme was not applied — set data-theme="${options.theme}" on <html> in ${name}`);
    }
  }

  if (command === 'init') {
    console.log('\n  Next: npx mms-ds start\n');
    return;
  }

  const { port } = await listen(options.port);
  const url = `http://localhost:${port}/`;

  console.log(`✓ Serving this folder at ${url}`);
  console.log(`\n  Edit ${name} and refresh. Press Ctrl+C to stop.\n`);

  if (options.open) openBrowser(url);
}

main().catch(error => fail(error.message));
